        res = {'text': ac.text(), 'enabled': ac.isEnabled(), 'visible': ac.isVisible()}
# also check attr names
res['attrs'] = [a for a in dir(mm) if 'project' in a.lower() or 'convert' in a.lower()]
result = res"}
